Now create the reliable unpipe module. Let me design it.

`unpipe-all.js`:

```js
import unpipe from "unpipe";

/**
 * Reliably remove every destination currently piped from `source`.
 *
 * Node's `readable.unpipe()` without an argument only understands the
 * destinations it recorded in `_readableState.pipes`. Streams that were piped
 * through a wrapper, or piped more than once, can leave stale destinations
 * behind. This walks the recorded pipes (single or array), falls back to the
 * `unpipe` package, and finally detaches our own tracked set, so no
 * destination keeps receiving data.
 */
const tracked = new WeakMap();

export function track(source) {
  if (!tracked.has(source)) tracked.set(source, new Set());
  return tracked.get(source);
}

export function pipeTo(source, destination, options) {
  track(source).add(destination);
  return source.pipe(destination, options);
}

export function unpipeAll(source) {
  if (!source || typeof source.unpipe !== "function") return source;

  const destinations = new Set(tracked.get(source) ?? []);
  const state = source._readableState;
  const pipes = state && state.pipes;
  if (Array.isArray(pipes)) {
    for (const dest of pipes) destinations.add(dest);
  } else if (pipes) {
    destinations.add(pipes);
  }

  // Handles the common cases (single or array) exactly like the `unpipe` pkg.
  try {
    unpipe(source);
  } catch {
    // ignore and fall through to the explicit detach below
  }

  // `unpipe()` records nothing for destinations we tracked ourselves.
  for (const destination of destinations) {
    try {
      source.unpipe(destination);
    } catch {
      // already detached
    }
  }

  tracked.get(source)?.clear();
  return source;
}
```

Hmm, but there's a subtlety: `unpipe` package's `unpipe(source)` reads `stream._readableState.pipes` and calls `stream.unpipe(dest)`. That should work for the standard case. But if `_readableState.pipes` is an array with duplicates it handles them. Good.

